        code: `def cost_plus_equal(n):
    # จำลอง result += ch : รอบที่ k ต้องคัดลอกสตริงยาว k ตัวไปที่ใหม่
    total = 0
    for k in range(1, n + 1):
        total += k
    return total


def cost_join(n):
    # จำลอง list.append n ครั้ง (ครั้งละตัว) แล้ว join คัดลอกรวมอีกรอบเดียว
    return n + n


for n in [10, 200, 100000]:
    print("n =", n, "-> += เขียน", cost_plus_equal(n), "ตัว, join เขียน", cost_join(n), "ตัว")`,
