                code: `from itertools import zip_longest


def merge_with_zip(word1: str, word2: str) -> str:
    parts = []
    for a, b in zip(word1, word2):        # zip ตัดที่ฝั่งสั้นสุด
        parts.append(a)
        parts.append(b)
    k = min(len(word1), len(word2))       # จึงต้องคำนวณจุดตัดแล้วต่อหางเองอยู่ดี
    parts.append(word1[k:])
    parts.append(word2[k:])
    return "".join(parts)


def merge_with_zip_longest(word1: str, word2: str) -> str:
    return "".join(a + b for a, b in zip_longest(word1, word2, fillvalue=""))


for w1, w2 in [("abc", "pqr"), ("ab", "pqrs"), ("abcd", "pq"), ("a", "")]:
    print(merge_with_zip(w1, w2), merge_with_zip_longest(w1, w2))`,
