        label: "พิสูจน์ด้วยการไล่ทุกเคส — สูตรกับ brute force ตอบตรงกันหมดไหม",
        code: `from itertools import product
from math import gcd


def brute_force(str1, str2):
    # วิธีที่ 1: ไล่ความยาวบล็อกจากมากไปน้อย ไม่ใช้ทฤษฎีอะไรเลย
    for k in range(min(len(str1), len(str2)), 0, -1):
        cand = str1[:k]
        if len(str1) % k == 0 and len(str2) % k == 0:
            if cand * (len(str1) // k) == str1 and cand * (len(str2) // k) == str2:
                return cand
    return ""


def by_trick(str1, str2):
    # วิธีที่ 2: สูตรสองบรรทัดที่เรากำลังจะพิสูจน์
    if str1 + str2 != str2 + str1:
        return ""
    return str1[:gcd(len(str1), len(str2))]


# สร้าง string ทุกตัวที่ยาว 1 ถึง 8 จากตัวอักษร a กับ b
words = []
for length in range(1, 9):
    for letters in product("ab", repeat=length):
        words.append("".join(letters))

tested = 0
mismatched = 0
for s1 in words:
    for s2 in words:
        tested += 1
        if brute_force(s1, s2) != by_trick(s1, s2):
            mismatched += 1

print("จำนวน string ที่ใช้ทดสอบ :", len(words))
print("จำนวนคู่ที่ลองทั้งหมด    :", tested)
print("จำนวนคู่ที่สองวิธีตอบไม่ตรงกัน :", mismatched)`,
