            code: `from math import gcd


def without_check(str1, str2):
    # ผิด: ข้ามด่านเช็ค concat แล้วตัด prefix ตาม gcd เลย
    return str1[:gcd(len(str1), len(str2))]


def with_check(str1, str2):
    # ถูก: ต้องผ่านด่านเช็คก่อน
    if str1 + str2 != str2 + str1:
        return ""
    return str1[:gcd(len(str1), len(str2))]


for a, b in [("ABCABC", "ABC"), ("LEET", "CODE"), ("ABAB", "ABBA"), ("AB", "BA")]:
    print(a, "/", b, "| ไม่เช็ค:", repr(without_check(a, b)), "| เช็ค:", repr(with_check(a, b)))`,
