                label: "ไล่เคสขอบทั้งหมด",
                code: `from math import gcd


def gcd_of_strings(str1: str, str2: str) -> str:
    if str1 + str2 != str2 + str1:
        return ""
    return str1[:gcd(len(str1), len(str2))]


cases = [
    ("ABC", "ABC"),                       # เหมือนกันเป๊ะ
    ("A", "A"),                           # สั้นที่สุดที่ constraint ยอมให้
    ("A", "B"),                           # ตัวเดียวแต่คนละตัว
    ("AAAAAA", "AA"),                     # บล็อกเป็นตัวอักษรตัวเดียวซ้ำ
    ("ABCDEF", "ABC"),                    # ขึ้นต้นเหมือนกันแต่ไม่ใช่บล็อก
    ("ABABAB", "ABABABABAB"),             # str2 ยาวกว่า str1
]

for a, b in cases:
    print(a.ljust(12), "/", b.ljust(12), "->", repr(gcd_of_strings(a, b)))`,
