        label: "โค้ดสองแบบที่เป็นอันเดียวกัน",
        code: `candies = [2, 3, 5, 1, 3]
extra = 3
best = max(candies)

# แบบที่ 1 — for loop เต็มรูป เขียนยาวแต่เห็นทุกขั้นตอน
answer1 = []
for c in candies:
    answer1.append(c + extra >= best)

# แบบที่ 2 — list comprehension คือแบบที่ 1 ทั้งดุ้น เขียนย่อเป็นบรรทัดเดียว
answer2 = [c + extra >= best for c in candies]

print("แบบ for loop        :", answer1)
print("แบบ comprehension   :", answer2)
print("ได้ผลเหมือนกันไหม   :", answer1 == answer2)`,
        out: `แบบ for loop        : [True, True, True, False, True]
แบบ comprehension   : [True, True, True, False, True]
ได้ผลเหมือนกันไหม   : True`,
