        label: "บังคับให้ดอกแรกไม่ลงซ้ายสุด แล้วเกิดอะไรขึ้น",
        code: `def is_legal(bed):
    for i in range(len(bed) - 1):
        if bed[i] == 1 and bed[i + 1] == 1:
            return False
    return True


def fill_after(bed, first):
    """บังคับให้ดอกแรกลงที่ตำแหน่ง first แล้วที่เหลือปลูกแบบซ้ายสุดตามปกติ"""
    new_bed = list(bed)
    new_bed[first] = 1
    if not is_legal(new_bed):
        return None, 0
    count = 1
    for i in range(first + 1, len(new_bed)):
        if new_bed[i] == 0:
            left_ok = new_bed[i - 1] == 0
            right_ok = i == len(new_bed) - 1 or new_bed[i + 1] == 0
            if left_ok and right_ok:
                new_bed[i] = 1
                count += 1
    return new_bed, count


bed = [0, 0, 0, 0, 0]
print("แปลงตั้งต้น", bed)
for first in range(len(bed)):
    result, count = fill_after(bed, first)
    print("  ดอกแรกลงที่ index", first, "-> แปลงจบที่", result, "ปลูกได้", count, "ดอก")`,
