            label: "เฉลย (Python) — O(n) time, O(n) space จากการก็อป (เป็น O(1) ได้ถ้ายอมแก้ลิสต์เดิม)",
            code: `def can_place_flowers(flowerbed: list[int], n: int) -> bool:
    bed = flowerbed[:]                                     # (1) ก็อปก่อน ไม่แตะ input ต้นฉบับ
    size = len(bed)
    count = 0                                              # (2) ปลูกไปแล้วกี่ดอก
    for i in range(size):                                  # (3) กวาดซ้าย -> ขวา รอบเดียว
        if bed[i] == 0:                                    # (4) ช่องนี้ต้องว่างก่อน
            left_ok = i == 0 or bed[i - 1] == 0            # (5) ไม่มีเพื่อนบ้านซ้าย หรือซ้ายว่าง
            right_ok = i == size - 1 or bed[i + 1] == 0    # (6) ไม่มีเพื่อนบ้านขวา หรือขวาว่าง
            if left_ok and right_ok:
                bed[i] = 1                                 # (7) ปลูกจริง ให้ช่องถัดไปเห็น
                count += 1
                if count >= n:                             # (8) ครบแล้วออกเลย
                    return True
    return count >= n                                      # (9) เผื่อกรณี n = 0


print(can_place_flowers([1, 0, 0, 0, 1], 1))
print(can_place_flowers([1, 0, 0, 0, 1], 2))
print(can_place_flowers([0], 1))
print(can_place_flowers([0, 0], 1))
print(can_place_flowers([0, 0], 2))
print(can_place_flowers([1, 0, 0, 0, 0, 1], 2))
print(can_place_flowers([0, 0, 1, 0, 0], 2))
print(can_place_flowers([1, 0, 1, 0, 1], 0))`,
