            c: "หลายคนคิดว่าในเมื่อโจทย์ถามแค่จำนวน ก็บวก count อย่างเดียวก็พอ ไม่ต้องไปแก้ลิสต์ให้เปลืองแรง ผลคือช่องถัดไปยังมองเห็นซ้ายมือเป็นช่องว่าง แล้วปลูกซ้อนติดกันได้ทั้งแถว ทำให้นับเกินจริงและตอบ true ในเคสที่ควรตอบ false ดูผลจริงข้างล่าง",
