                label: "สูตรช่วงช่องว่าง — ไม่แตะ input เลย และเทียบกับ greedy ทุกเคส",
                code: `def can_place_flowers_gap(flowerbed, n):
    """ไม่แตะ input เลย: นับความยาวของช่วงช่องว่างแล้วใช้สูตร"""
    count = 0
    run = 1                       # เริ่มที่ 1 = นับ "นอกแปลงทางซ้าย" เป็นช่องว่างไปด้วย
    for x in flowerbed:
        if x == 0:
            run += 1
        else:
            count += (run - 1) // 2
            run = 0
    run += 1                      # นับ "นอกแปลงทางขวา" เป็นช่องว่างอีกช่อง
    count += (run - 1) // 2
    return count >= n


def greedy(flowerbed, n):
    bed = list(flowerbed)
    size = len(bed)
    count = 0
    for i in range(size):
        if bed[i] == 0:
            left_ok = i == 0 or bed[i - 1] == 0
            right_ok = i == size - 1 or bed[i + 1] == 0
            if left_ok and right_ok:
                bed[i] = 1
                count += 1
    return count >= n


bad = 0
tested = 0
for size in range(1, 12):
    for mask in range(1 << size):
        bed = [(mask >> i) & 1 for i in range(size)]
        legal = True
        for i in range(size - 1):
            if bed[i] == 1 and bed[i + 1] == 1:
                legal = False
        if not legal:
            continue
        for n in range(0, size + 1):
            tested += 1
            if can_place_flowers_gap(bed, n) != greedy(bed, n):
                bad += 1
                print("ต่างกัน:", bed, n)

original = [1, 0, 0, 0, 1]
print(can_place_flowers_gap(original, 1))
print("input หลังเรียกฟังก์ชัน =", original, "(ไม่ถูกแก้เลย)")
print("เทียบกับ greedy ทั้งหมด", tested, "เคส ต่างกัน", bad, "เคส")`,
