        code: `def scan(s, use_break):
    words = []
    i, n = 0, len(s)
    while i < n:
        while i < n and s[i] == " ":
            i += 1
        if i == n and use_break:        # บรรทัดที่เป็นประเด็น
            break
        start = i
        while i < n and s[i] != " ":
            i += 1
        words.append(s[start:i])
    return words


s = "  hello world  "
a = scan(s, True)
b = scan(s, False)
print("มี break    :", a, "-> ต่อกลับได้", repr(" ".join(reversed(a))))
print("ไม่มี break  :", b, "-> ต่อกลับได้", repr(" ".join(reversed(b))))`,
