                code: `def reverse_range(chars, a, b):
    while a < b:                                 # กลับตัวอักษรช่วง [a, b] ในที่เดิม
        chars[a], chars[b] = chars[b], chars[a]
        a += 1
        b -= 1


def squeeze_spaces(chars):                       # (1) บีบช่องว่างเกินออก แก้ในที่เดิม
    n = len(chars)
    write = 0
    read = 0
    while read < n:
        if chars[read] == " ":
            read += 1
            continue
        if write != 0:                           # ไม่ใช่คำแรก -> คั่นหนึ่งช่อง
            chars[write] = " "
            write += 1
        while read < n and chars[read] != " ":   # คัดตัวอักษรของคำมาชิดซ้าย
            chars[write] = chars[read]
            write += 1
            read += 1
    del chars[write:]                            # ตัดหางทิ้ง (เทียบเท่า resize)


def reverse_each_word(chars):                    # (3) กลับตัวอักษรของแต่ละคำคืน
    m = len(chars)
    start = 0
    for i in range(m + 1):
        if i == m or chars[i] == " ":
            reverse_range(chars, start, i - 1)
            start = i + 1


for s in ["the sky is blue", "  hello world  ", "a good   example"]:
    chars = list(s)                              # จำลอง string ที่แก้ในที่เดิมได้
    print("เริ่ม         :", repr("".join(chars)))
    squeeze_spaces(chars)
    print("  (1) บีบช่องว่าง:", repr("".join(chars)))
    reverse_range(chars, 0, len(chars) - 1)      # (2) กลับทั้งแถวหนึ่งครั้ง
    print("  (2) กลับทั้งแถว:", repr("".join(chars)))
    reverse_each_word(chars)
    print("  (3) กลับทีละคำ :", repr("".join(chars)))
    print()`,
                out: `เริ่ม         : 'the sky is blue'
  (1) บีบช่องว่าง: 'the sky is blue'
  (2) กลับทั้งแถว: 'eulb si yks eht'
  (3) กลับทีละคำ : 'blue is sky the'

เริ่ม         : '  hello world  '
  (1) บีบช่องว่าง: 'hello world'
  (2) กลับทั้งแถว: 'dlrow olleh'
  (3) กลับทีละคำ : 'world hello'

เริ่ม         : 'a good   example'
  (1) บีบช่องว่าง: 'a good example'
  (2) กลับทั้งแถว: 'elpmaxe doog a'
  (3) กลับทีละคำ : 'example good a'`,
