        code: `def compress_to_new_list(chars):
    out = []                                       # กระดาษแผ่นใหม่ ยังไม่แตะของเดิม
    i = 0
    while i < len(chars):
        ch = chars[i]                              # ตัวอักษรที่เปิดกลุ่มนี้
        count = 0
        while i < len(chars) and chars[i] == ch:   # กินทั้งกลุ่มที่ติดกัน
            i += 1
            count += 1
        out.append(ch)                             # เขียนตัวอักษรหนึ่งตัว
        if count > 1:                              # ซ้ำตัวเดียวไม่ต้องเขียนเลข
            for d in str(count):                   # เลขหลายหลักเขียนทีละหลัก
                out.append(d)
    return out


tests = [
    ["a", "a", "b", "b", "c", "c", "c"],
    ["a"],
    ["a"] + ["b"] * 12,
]
for chars in tests:
    out = compress_to_new_list(chars)
    print(len(out), out)`,
